package io.github.arkivx0.lanternly

import io.github.arkivx0.lanternly.core.*
import org.json.JSONObject
import org.junit.Assert.*
import org.junit.Test
import java.util.UUID

/** Same vectors as the Windows tests (spec/test_vectors.json and spec/keyfile_vector.json, generated by independent Python reference code). */
class ProtocolTest {
    private val v = JSONObject(javaClass.classLoader!!.getResourceAsStream("test_vectors.json")!!.bufferedReader().readText())
    private fun hex(b: ByteArray) = b.joinToString("") { "%02x".format(it) }
    private fun unhex(s: String) = ByteArray(s.length / 2) { s.substring(it * 2, it * 2 + 2).toInt(16).toByte() }

    @Test fun ble() {
        assertEquals(v.getString("ble_key_encrypt").substring(0, 16), hex(Ble.pairRequest("AABBCCDDEEFF", "12345678", byteArrayOf(1, 2, 3, 4, 5, 6, 7, 8)).copyOfRange(9, 17)))
        val sk = Ble.sessionKey("AABBCCDDEEFF", "12345678", byteArrayOf(1, 2, 3, 4, 5, 6, 7, 8), byteArrayOf(0x0d, 0x20, 0x21, 0x22, 0x23, 0x24, 0x25, 0x26, 0x27))
        assertEquals(v.getString("ble_sk"), hex(sk))
        val mac = Ble.macLe("AA:BB:CC:DD:EE:FF")
        assertEquals(v.getString("ble_enc"), hex(Ble.command(sk, mac, 0x1234, 5, Ble.CMD_BRIGHTNESS, Ble.brightnessData(60))))
        assertEquals(v.getString("ble_dec_of_enc"), hex(Ble.decryptNotify(sk, mac, unhex(v.getString("ble_enc")))))
        assertThrows(SecurityException::class.java) { Ble.sessionKey("a", "b", ByteArray(8), ByteArray(9) { 0x0e }) }
    }

    @Test fun caps() { assertTrue(Caps.count > 100); assertTrue(Caps.forType(6) and Caps.COLOR != 0); assertEquals(Caps.ON_OFF or Caps.DIM, Caps.forType(99999)) }

    @Test fun vaultRoundTripAndOldCloudFieldsAreDropped() {
        val v1 = Vault(listOf(Home(7, "H", "M", "P", listOf(Room(1, "R", listOf(2))), mutableListOf(Bulb("B", 2, 6, "AA:BB:CC:DD:EE:01")))))
        val v2 = Vault.fromJson(v1.toJson())
        assertEquals("P", v2.homes[0].meshPassword); assertEquals(2, v2.homes[0].rooms[0].meshIds[0])
        val old = Vault.fromJson("""{"Format":1,"Homes":[{"Id":1,"MeshName":"m","MeshPassword":"p","Bulbs":[{"Name":"x","DeviceId":5,"MeshId":2}]}],"Cloud":{"AccessToken":"secret"}}""")
        assertEquals("p", old.homes[0].meshPassword); assertFalse(old.toJson().contains("secret"))
    }

    @Test fun keyFileReadsReferenceVector() {
        val kv = JSONObject(javaClass.classLoader!!.getResourceAsStream("keyfile_vector.json")!!.bufferedReader().readText())
        assertEquals(kv.getString("mesh_password"), KeyFile.import(kv.getString("file"), kv.getString("passphrase")).homes[0].meshPassword)
    }

    @Test fun keyFileRoundTrip() {
        val v = Vault(listOf(home()))
        val prot = KeyFile.export(v, "correct horse")
        assertTrue(KeyFile.isProtected(prot)); assertFalse(prot.contains("123456"))
        assertEquals("123456", KeyFile.import(prot, "correct horse").homes[0].meshPassword)
        assertThrows(KeyFile.WrongPassphrase::class.java) { KeyFile.import(prot, "wrong") }
        assertThrows(KeyFile.WrongPassphrase::class.java) { KeyFile.import(prot, null) }
        assertEquals("123456", KeyFile.import(KeyFile.export(v, null), null).homes[0].meshPassword)
    }

    @Test fun colorTempZeroIsClampedToOne() = assertEquals(1, Ble.colorTempData(0)[1].toInt())

    @Test fun batchAndSceneReportPartialSuccess() {
        val h = home()
        val flaky = object : Link {
            override val kind = Via.BLE; override var onState: ((Home?, BulbState) -> Unit)? = null
            override fun canReach(h: Home, b: Bulb) = true
            override fun send(h: Home, b: Bulb, c: Cmd) { if (b.name == "Desk") throw java.io.IOException("radio busy") }
        }
        val r = Router(listOf(flaky))
        assertEquals("1/2 bulbs updated (Desk: radio busy)", r.sendMany(h, h.bulbs, Cmd.Power(true)).toString())
        val sc = Scenes.apply(r, h, Scenes.all[0]); assertEquals(1, sc.ok); assertFalse(sc.allOk)
        assertThrows(NotReachable::class.java) { Router(emptyList()).send(h, h.bulbs[0], Cmd.Power(true)) }
    }

    // ---- end to end with fakes ----
    private fun home() = Home(50, "T", "AABBCCDDEEFF", "123456", listOf(Room(1, "Office", listOf(2, 3))),
        mutableListOf(Bulb("Lamp", 2, 6, "AA:BB:CC:DD:EE:01"), Bulb("Desk", 3, 6, "AA:BB:CC:DD:EE:02")))

    @Test fun factoryPairingWriteMatchesPublishedConstant() =
        assertEquals("0ca0a1a2a3a4a5a6a78db674711b855a79", hex(Ble.pairRequest("telink_mesh1", "123", ByteArray(8) { (0xa0 + it).toByte() })))

    @Test fun adoptResetBulb() {
        val node = FakeNode("AA:BB:CC:DD:EE:09", Ble.FACTORY_NAME, Ble.FACTORY_PASSWORD)
        val (n, p) = Ble.newMeshCredentials()
        BleSession.provision(node, n, p)
        val h = Home(1, "Mine", n, p, emptyList(), mutableListOf(Bulb("Red lamp", 0, Caps.ALL_CONTROLS, node.mac)))
        val s = BleSession(node, h); s.login()
        assertEquals(Via.BLE, Router(listOf(s)).send(h, h.bulbs[0], Cmd.Power(true)))
        assertTrue(h.bulbs[0].has(Caps.COLOR))
    }

    private class FakeNode(override val mac: String, var name: String, var pass: String) : GattPort {
        var newName: ByteArray? = null; var newPass: ByteArray? = null
        private fun dec(x: ByteArray): ByteArray {
            val c = javax.crypto.Cipher.getInstance("AES/ECB/NoPadding"); c.init(javax.crypto.Cipher.DECRYPT_MODE, javax.crypto.spec.SecretKeySpec(sk!!.reversedArray(), "AES"))
            return c.doFinal(x.copyOfRange(1, 17).reversedArray()).reversedArray()
        }
        var sk: ByteArray? = null; var reply = ByteArray(0); val plain = ArrayList<ByteArray>()
        override fun write(ch: UUID, data: ByteArray, withResponse: Boolean) {
            if (ch == Ble.PAIR && data[0].toInt() in 4..6) {
                when (data[0].toInt()) { 4 -> newName = dec(data); 5 -> newPass = dec(data)
                    else -> { name = String(newName!!).trimEnd('\u0000'); pass = String(newPass!!).trimEnd('\u0000'); reply = byteArrayOf(7) } }
            } else if (ch == Ble.PAIR) {
                val r = data.copyOfRange(1, 9)
                reply = if (Ble.pairRequest(name, pass, r).contentEquals(data)) byteArrayOf(0x0d, 9, 8, 7, 6, 5, 4, 3, 2) + ByteArray(8) else ByteArray(17) { 0x0e }
                if (reply[0] == 0x0d.toByte()) sk = Ble.sessionKey(name, pass, r, reply)
            } else if (ch == Ble.COMMAND) {
                val m = Ble.macLe(mac); val p = data.copyOf()
                val ks = Ble.aes(sk!!, byteArrayOf(0, m[0], m[1], m[2], m[3], 1, p[0], p[1], p[2], 0, 0, 0, 0, 0, 0, 0))
                for (i in 0 until 15) p[i + 5] = (p[i + 5].toInt() xor ks[i].toInt()).toByte()
                val chk = Ble.encryptPacket(sk!!, m, p.copyOf().also { it[3] = 0; it[4] = 0 })
                assertArrayEquals(data.copyOfRange(3, 5), chk.copyOfRange(3, 5))
                plain += p
            }
        }
        override fun read(ch: UUID) = reply
        override fun subscribe(ch: UUID, onNotify: (ByteArray) -> Unit) {}
        override fun close() {}
    }

    @Test fun bleSessionEndToEnd() {
        val h = home(); val node = FakeNode(h.bulbs[0].mac, h.meshName, h.meshPassword)
        val s = BleSession(node, h); s.login()
        assertEquals(Via.BLE, Router(listOf(s)).send(h, h.bulbs[1], Cmd.Rgb(1, 2, 3)))
        val p = node.plain.single()
        assertEquals(3, p[5].toInt()); assertEquals(Ble.CMD_COLOR, p[7].toInt() and 0xff)
        assertArrayEquals(byteArrayOf(4, 1, 2, 3), p.copyOfRange(10, 14))
        val bad = BleSession(FakeNode(h.bulbs[0].mac, h.meshName, "nope"), h)
        assertThrows(SecurityException::class.java) { bad.login() }
    }
}
